using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            using var transaction = db.Database.BeginTransaction();
            db.Database.Migrate();
            transaction.Commit();
        });
    }

    // EF9 breaking change: Synchronous I/O on Cosmos DB is no longer supported.
    // All Cosmos DB queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.).
    async Task QueryCosmosAsync(CosmosDbContext cosmosDb)
    {
        // BEFORE (EF8 - would throw InvalidOperationException in EF9):
        //   var products = cosmosDb.Products.ToList();
        //   var first = cosmosDb.Products.First();

        // AFTER (EF9 - use async APIs):
        var products = await cosmosDb.Products.ToListAsync();
        var first = await cosmosDb.Products.FirstOrDefaultAsync();
    }
}

